def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    opp_def_total = 0
    me_def_total = 0
    for i in range(n):
        if opp[i] == 'D':
            opp_def_total += 1
        if me[i] == 'D':
            me_def_total += 1

    # Pure defector: match it, no point in feeding it.
    if opp_def_total == n and n >= 2:
        return 'D'
    # Pure cooperator: farm near the end, otherwise keep the mutual CC train.
    if opp_def_total == 0:
        if n >= 92:
            return 'D'
        if n >= 20 and rng.random() < 0.06:
            return 'D'
        return 'C'

    # Strong recent defection pressure.
    recent_opp = opp[-12:]
    recent_opp_def = 0
    for a in recent_opp:
        if a == 'D':
            recent_opp_def += 1

    if recent_opp_def >= 9:
        return 'D'
    if recent_opp_def >= 6 and n >= 8:
        if opp[-1] == 'D':
            return 'D'
        if rng.random() < 0.55:
            return 'D'
        return 'C'

    last_opp = opp[-1]
    last_me = me[-1]

    # Detect a burst of fresh defections after a cooperative stretch.
    if n >= 18:
        recent5 = opp[-5:]
        r5d = 0
        for a in recent5:
            if a == 'D':
                r5d += 1
        earlier = opp[-20:-5]
        ed = 0
        for a in earlier:
            if a == 'D':
                ed += 1
        if r5d >= 3 and ed <= 2:
            return 'D'

    # Tit-for-tat flavored retaliation with measured forgiveness.
    if last_opp == 'D':
        if last_me == 'C':
            # Fresh hit. Retaliate, but if opponent has been very clean retry cooperation sooner.
            if opp_def_total <= 2:
                if n >= 2 and opp[-2] == 'C' and opp_def_total == 1:
                    return 'D'
                if rng.random() < 0.65:
                    return 'D'
                return 'C'
            if recent_opp_def >= 4:
                return 'D'
            if rng.random() < 0.85:
                return 'D'
            return 'C'
        else:
            # Both defected. Try to climb back to CC if a short break exists.
            if n >= 4:
                if opp[-2] == 'C' and opp[-3] == 'C':
                    return 'C'
            if opp_def_total * 3 <= n:
                if rng.random() < 0.4:
                    return 'C'
                return 'D'
            return 'D'

    # Opponent cooperated last.
    if recent_opp_def >= 3:
        # Mistrust, but don't spiral into endless DD.
        if me_def_total > opp_def_total + 2:
            return 'C'
        if rng.random() < 0.35:
            return 'D'
        return 'C'

    # Occasionally probe a very clean opponent late to skim DC.
    if n >= 88 and opp_def_total <= 3:
        if last_opp == 'C':
            return 'D'
    if n >= 30 and opp_def_total <= max(1, n // 25):
        if rng.random() < 0.07:
            return 'D'

    return 'C'
